mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("n=4 edges=(0,1),(1,2),(1,3)","5,3,5,5"),
        ("n=3 edges=(0,1),(1,2)","3,2,3"),
        ("n=1 edges=","0"),
        ("n=4 edges=(0,1),(1,2),(2,3)","6,4,4,6"),
        ("n=5 edges=(0,1),(0,2),(0,3),(0,4)","4,7,7,7,7"),
        ("  \nn=4 edges=(0,1),(1,2),(1,3)\n  ","5,3,5,5"),
        ("\nn=5 edges=(0,1),(0,2),(0,3),(0,4)\n","4,7,7,7,7")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS tree-rerooting");
}
